40	pub(crate) fn order_by_object_type(
41	    ctx: &'_ QuerySchema,
42	    container: ParentContainer,
43	    options: OrderByOptions,
44	) -> InputObjectType<'_> {
45	    let ident = Identifier::new_prisma(IdentifierType::OrderByInput(
46	        container.clone(),
47	        options.type_suffix().to_owned(),
48	    ));
49	
50	    let mut input_object = init_input_object_type(ident);
51	    input_object.require_at_most_one_field();
52	    input_object.set_fields(move || {
53	        // Basic orderBy fields.
54	        let mut fields: Vec<_> = container
55	            .fields()
56	            .iter()
57	            .filter_map(|field| match field {
58	                // We exclude composites if we're in aggregations land (groupBy).
59	                ModelField::Composite(_) if options.include_scalar_aggregations => None,
60	                _ => orderby_field_mapper(field, ctx, options),
61	            })
62	            .collect();
63	
64	        if options.include_scalar_aggregations {
65	            // orderBy Fields for aggregation orderings.
66	            fields.extend(compute_scalar_aggregation_fields(container.clone()));
67	        }
68	
69	        if options.include_full_text_search {
70	            // orderBy Fields for full text searches.
71	            append_opt(&mut fields, order_by_field_text_search(container.clone()))
72	        }
73	
74	        fields
75	    });
76	    input_object
77	}
