    let selection: Vec<_> = rs
        .args
        .order_by
        .iter()
        .flat_map(|order_by| match order_by {
            // If the ordering is on a scalar field of the model itself, we need to select that field.
            OrderBy::Scalar(x) if x.path.is_empty() => vec![x.field.clone()],
            // If the ordering traverses relations, the actual ordering (and the joins it requires)
            // is performed on the outer query. For the first hop's join to work, we need to select
            // the linking fields of that first hop so they're available on the outer query.
            OrderBy::Scalar(x) => first_hop_linking_fields(&x.path),
            OrderBy::ToManyAggregation(x) => first_hop_linking_fields(&x.path),
            OrderBy::Relevance(x) => x.fields.clone(),
            _ => Vec::new(),
        })
        .collect();

    FieldSelection::from(selection)
}

/// Returns the scalar linking fields of the first hop of an orderBy path.
///
/// When ordering by a nested relation path, the ordering itself is computed on the outer query via
/// joins. The join for the very first hop links back to the (sub)query that fetches the records
/// being ordered, so the linking fields of that first hop must be part of that query's selection.
fn first_hop_linking_fields(hops: &[OrderByHop]) -> Vec<ScalarFieldRef> {
    match hops.first().and_then(|hop| hop.as_relation_hop()) {
        Some(rf) => rf.left_scalars(),
        _ => Vec::new(),
    }
